insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.559328, 0.218695, 'junction', 'Tight junction — position early and check both mirrors before turning.', 'medium' from routes where name = 'Route 9 · Wingletye Lane and Ardleigh Green Road' and centre_id = (select id from test_centres where name = 'Hornchurch');
