insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.640671, 0.068349, 'junction', 'Tight junction — position early and check both mirrors before turning.', 'medium' from routes where name = 'Route 2 · Oakwood Hill and Abridge Road' and centre_id = (select id from test_centres where name = 'Loughton');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.627128, 0.048163, 'roundabout', 'Busy roundabout — mirror-signal-position on approach, watch lane discipline on exit.', 'low' from routes where name = 'Route 2 · Oakwood Hill and Abridge Road' and centre_id = (select id from test_centres where name = 'Loughton');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.627112, 0.046197, 'zebra', 'Pedestrian crossing — scan pavements early and be ready to stop smoothly.', 'medium' from routes where name = 'Route 2 · Oakwood Hill and Abridge Road' and centre_id = (select id from test_centres where name = 'Loughton');
