insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.62775, 0.083168, 'zebra', 'Pedestrian crossing — scan pavements early and be ready to stop smoothly.', 'medium' from routes where name = 'Route 5 · North Circular Road and Hainault Road' and centre_id = (select id from test_centres where name = 'Loughton');
