insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.42561, 0.104426, 'zebra', 'Pedestrian crossing — scan pavements early and be ready to stop smoothly.', 'medium' from routes where name = 'Route 10 · Burnt Oak Lane and Elm Road' and centre_id = (select id from test_centres where name = 'Sidcup');
