insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 52.395816, -1.501167, 'roundabout', 'Busy roundabout — mirror-signal-position on approach, watch lane discipline on exit.', 'low' from routes where name = 'Route 7 · The Mount and William Bristow Road' and centre_id = (select id from test_centres where name = 'Coventry');
