insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'safety', 'Show me how you''d check that the tyres on this car have sufficient tread depth and are in a safe condition to drive.', 'I''d check the tread depth is at least 1.6mm across the central three-quarters of the tyre''s width, look for cuts or bulges, and check the pressures with a gauge if one is available.', true);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Show me how you''d check that the horn is working (off road only).', 'I''d press the horn control, usually found on the steering wheel, to sound it briefly.', true);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Show me how you''d set the demister controls to clear all the windows effectively.', 'I''d switch on the fan and heater, select the windscreen setting, choose a warm airflow, and switch on the heated rear window and air conditioning if fitted.', true);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Show me how you''d switch your headlights from dipped to main beam and explain how you''d know the main beam is on.', 'I''d move the indicator stalk forward, or press the light switch, to select main beam, and a blue warning light on the dashboard confirms it''s on.', true);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Show me how you''d check the footbrake is working effectively as you move away, without the car pulling to either side.', 'As I move off, I''d press the brake pedal firmly and check the car stops smoothly and promptly, travelling in a straight line without pulling to one side.', true);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Show me how you''d clean the windscreen using the windscreen washer and wiper.', 'I''d operate the washer stalk or button so washer fluid sprays the screen, then let the wipers clear it, repeating until the screen is clean.', true);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Show me how you''d switch on your rear fog light(s) and explain when you''d use it/them.', 'I''d pull out or press the switch marked with a light symbol crossed by three horizontal lines, and I''d only use it when visibility drops below 100 metres.', true);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'safety', 'Tell me how you''d check that the brakes are working before starting a journey.', 'I''d press the brake pedal before moving off and check it feels firm, with no excessive travel and no sponginess.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'safety', 'Tell me where you''d find the recommended tyre pressures for this car and how you''d check them.', 'The recommended pressures are usually shown in the handbook, on a sticker inside the driver''s door sill, or on the fuel filler flap, and I''d check them with a pressure gauge when the tyres are cold.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'safety', 'Tell me how you''d check the head restraint is correctly adjusted so it provides the best protection in the event of a crash.', 'The head restraint should be adjusted so the rigid part is level with the top of my head, and as close to the back of my head as is comfortable.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'safety', 'Tell me how you''d check the tyres have sufficient tread depth and that their general condition is safe to use.', 'The legal minimum tread depth is 1.6mm across the central three-quarters of the tyre''s width around its entire circumference, and I''d also check for cuts and bulges.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Tell me how you''d check your headlights and sidelights are working, without getting out of the car.', 'I''d switch them on and check the dashboard light confirms they''re lit, and I could check their reflection in a window or ask someone to confirm they''re working.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Tell me how you''d know if there was a problem with your anti-lock braking system.', 'A warning light on the instrument panel would illuminate and stay lit if there''s a fault with the ABS.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Tell me how you''d check the direction indicators are working.', 'I''d switch on the hazard warning lights, or each indicator in turn, and walk round the vehicle to check all the lights are flashing, or ask someone to confirm while I operate them.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Tell me how you''d check the brake lights are working on this car.', 'With the ignition on, I''d operate the footbrake and use a reflection in a window or garage door, or ask someone to check the lights come on.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Tell me how you''d check the power-assisted steering is working before starting a journey.', 'If the steering feels unusually heavy, or there''s no resistance after gently turning the wheel and pulling away, it may indicate a fault, and a dashboard warning light would also alert me.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'inside_car', 'Tell me when you''d use front or rear fog lights and how you''d know they''re switched on.', 'I''d use them only when visibility is seriously reduced to less than 100 metres, and a warning light on the dashboard shows when they''re switched on.', false);
insert into show_me_tell_me (id, category, question, answer, is_show_me) values (gen_random_uuid(), 'under_bonnet', 'Open the bonnet and tell me how you''d check the engine has sufficient oil, coolant and brake fluid.', 'I''d check the oil sits between the minimum and maximum marks on the dipstick, the coolant is between the markers on the header tank, and the brake fluid is between the min and max lines on its reservoir.', false);
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Parallel park', '[{"title":"Choose your space","detail":"Find a gap roughly two car lengths long, indicate, and pull up alongside the car in front of the gap, about a car''s width away from it."},{"title":"Get into position","detail":"Line up so your rear bumper is roughly level with the other car''s rear bumper, select reverse, and check all around before moving."},{"title":"Begin reversing","detail":"Reverse slowly, steering fully towards the kerb once the car reaches roughly a 45-degree angle to it."},{"title":"Straighten up","detail":"As the car starts to come parallel to the kerb, steer smoothly the other way to bring the wheels straight."},{"title":"Final adjustment","detail":"Continue reversing slowly until the car is close to and parallel with the kerb, then stop."},{"title":"Check your position","detail":"Check you''re within about a car''s width of the kerb and not blocking a driveway, then apply the handbrake."}]'::jsonb, '{"Use reference points on your own car rather than fixed rules that apply to every road.","Keep the manoeuvre slow — speed makes it much harder to correct if you drift off line.","Pause for an all-round check at each stage rather than rushing through in one go."}');
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Bay park (reverse)', '[{"title":"Select a bay","detail":"Drive past the bay you plan to use, positioning the car roughly two bays away and parallel to the row."},{"title":"Prepare to reverse","detail":"Check all around, select reverse gear, and begin reversing slowly while checking mirrors and blind spots."},{"title":"Turn towards the bay","detail":"As the bay lines appear in your mirrors, steer towards the bay while continuing to check around the car."},{"title":"Straighten into the bay","detail":"Straighten the steering as the car lines up centrally between the bay markings."},{"title":"Reverse in fully","detail":"Continue reversing slowly until the car is parked centrally and fully within the bay lines."},{"title":"Secure the car","detail":"Apply the handbrake, select neutral or park, and check the car hasn''t crossed any of the bay lines."}]'::jsonb, '{"Move at a very slow, controlled speed throughout the manoeuvre.","Keep up continuous all-round observation, not just mirror checks.","If you drift off line, pull forward and start the turn again rather than forcing it."}');
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Forward bay park', '[{"title":"Approach the bay","detail":"Drive slowly through the car park and identify an empty bay ahead of you."},{"title":"Signal and position","detail":"Indicate if appropriate and position the car so you have enough room to turn into the bay."},{"title":"Turn in","detail":"Steer into the bay, checking mirrors and blind spots for pedestrians and other vehicles."},{"title":"Straighten up","detail":"Straighten the steering as the car lines up centrally within the bay markings."},{"title":"Drive in fully","detail":"Move forward until the car is parked centrally and square within the bay."},{"title":"Secure the car","detail":"Apply the handbrake and select neutral or park, checking the car is within the lines."}]'::jsonb, '{"Take it slowly — pedestrians can step out suddenly between parked cars.","Check the bay is wide enough and not reserved before you begin.","Use the bay lines and your car''s door pillars as reference points to stay central."}');
insert into manoeuvres (id, name, steps, tips) values (gen_random_uuid(), 'Pull up on the right', '[{"title":"Signal your intention","detail":"Check your mirrors and signal right in good time before pulling over."},{"title":"Position the car","detail":"Move over to a safe position close to the offside kerb, keeping clear of junctions and obstructions."},{"title":"Check before stopping","detail":"Check mirrors and blind spot again for traffic coming up behind or towards you before you stop."},{"title":"Stop safely","detail":"Bring the car to a stop parallel and close to the kerb, then apply the handbrake and select neutral."},{"title":"Prepare to move off","detail":"Signal right, then check mirrors and blind spot for oncoming and approaching traffic before moving away."},{"title":"Rejoin the road","detail":"Move off smoothly when it''s safe, crossing back to the correct side of the road promptly."}]'::jsonb, '{"Only use this manoeuvre where it''s legal and safe — never near a bend, junction or brow of a hill.","The blind-spot check matters more here since you''re pulling out into oncoming traffic.","Cancel your signal once you''ve safely moved off."}');
